package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.widget.*;import java.io.*;import java.util.*;
/** Real package disable/update/uninstall and actual plus action; disposable emulator only. */
public final class RemovedPinCheck extends Instrumentation {
 private Context c;private SettingsStore store;private HomeActivity home;private CatalogActivity chooser;private int checks;private final StringBuilder log=new StringBuilder();private final Map<String,Object> old=new HashMap<>();private long oldRevision;
 public void onCreate(Bundle b){super.onCreate(b);start();}private void check(boolean yes,String text){checks++;log.append(yes?"PASS ":"FAIL ").append(text).append('\n');if(!yes)throw new AssertionError(text);}private void main(Runnable action){runOnMainSync(action);waitForIdleSync();}interface Wait{boolean yes()throws Exception;}private void until(Wait condition)throws Exception{long end=SystemClock.uptimeMillis()+25000;while(!condition.yes()&&SystemClock.uptimeMillis()<end){VmWindows.clear(this);Thread.sleep(60);}check(condition.yes(),"await condition");}
 private String shell(String cmd)throws Exception{try(ParcelFileDescriptor p=getUiAutomation().executeShellCommand(cmd);InputStream in=new FileInputStream(p.getFileDescriptor());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 private void reload()throws Exception{AppCatalog catalog=AppCatalog.get(c);Object before=catalog.snapshot();main(catalog::reload);until(()->catalog.loaded()&&catalog.snapshot()!=before);}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();if(!Build.FINGERPRINT.contains("generic")&&!Build.MODEL.contains("Android SDK"))throw new AssertionError("VM only");VmWindows.prepare(this);store=new SettingsStore(c);oldRevision=store.slotsRevision();for(Map.Entry<String,?> e:store.data.getAll().entrySet())if(e.getKey().startsWith("slot."))old.put(e.getKey(),e.getValue());home=VmWindows.home(this);until(()->AppCatalog.get(c).loaded());
 main(()->{store.assign(0,"ru.truetv.probe");store.assign(1,"ru.truetv.probe");store.assign(34,"ru.truetv.probe");store.assign(2,"ru.truetv.session.tests");store.assign(3,"ru.truetv.truly.deletedfixture");});reload();check(store.slot(3).isEmpty(),"already missing package from old launcher becomes a real empty slot");check(store.slot(2).equals("ru.truetv.session.tests"),"installed package without launcher Activity remains pinned");check(((Tile)home.board.getChildAt(3)).pkg.isEmpty(),"stale missing tile is visually bound as plus");check(store.slot(0).equals("ru.truetv.probe"),"installed fixture preserved");
 check(shell("pm disable-user --user 0 ru.truetv.probe").contains("disabled"),"actual disable succeeds");reload();check(store.slot(0).equals("ru.truetv.probe")&&store.slot(34).equals("ru.truetv.probe"),"disabled package keeps visible and offscreen assignments");check(shell("pm enable ru.truetv.probe").contains("enabled"),"fixture enabled again");reload();
 check(shell("pm install -r /data/local/tmp/truetv-probe235.apk").contains("Success"),"actual APK replacement succeeds");reload();check(store.slot(0).equals("ru.truetv.probe")&&store.slot(1).equals("ru.truetv.probe")&&store.slot(34).equals("ru.truetv.probe"),"replacement broadcasts do not clear any duplicate/offscreen pins");
 Board board=home.board;check(shell("pm uninstall --user 0 ru.truetv.probe").contains("Success"),"actual package uninstall succeeds");until(()->store.slot(0).isEmpty()&&store.slot(1).isEmpty()&&store.slot(34).isEmpty());until(()->((Tile)home.board.getChildAt(0)).pkg.isEmpty());check(home.board==board,"uninstall refreshes existing tiles without recreating desktop");check(AppCatalog.get(c).find("ru.truetv.probe")==null,"uninstalled package is removed from live catalog immediately");check(store.slot(2).equals("ru.truetv.session.tests"),"uninstall does not remove another app's assignment");ActivityMonitor m=new ActivityMonitor(CatalogActivity.class.getName(),null,false);addMonitor(m);main(()->home.board.getChildAt(0).performClick());chooser=(CatalogActivity)waitForMonitorWithTimeout(m,15000);removeMonitor(m);check(chooser!=null,"former ghost slot now opens Add app instead of old package info");main(chooser::finish);chooser=null;
 long revision=store.slotsRevision();main(()->check(store.removePackages(Collections.singleton("ru.truetv.not.assigned"))==0,"unrelated uninstall changes no slots"));check(store.slotsRevision()==revision,"unrelated uninstall does not bump desktop revision");result.putBoolean("passed",true);
 }catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));log.append(w);result.putBoolean("passed",false);}finally{try{if(chooser!=null)main(chooser::finish);shell("pm install -r /data/local/tmp/truetv-probe235.apk");shell("pm enable ru.truetv.probe");main(()->{SharedPreferences.Editor edit=store.data.edit();for(int i=0;i<Choices.MAX_SLOTS;i++)edit.remove("slot."+i);for(Map.Entry<String,Object> e:old.entrySet())if(e.getValue() instanceof String)edit.putString(e.getKey(),(String)e.getValue());edit.putLong("desktop.slots_revision",oldRevision);edit.commit();});}catch(Exception e){log.append("RESTORE ").append(e);}}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
